const AWS = require('aws-sdk');

// Lambda handler for processing webhook events from internal services
exports.handler = async (event) => {
  const requestId = event.headers?.['x-request-id'] || 'unknown';
  const sourceService = event.headers?.['x-forwarded-for'] || 'unknown';
  const userAgent = event.headers?.['user-agent'] || 'unknown';

  // Parse the incoming webhook payload
  let payload;
  try {
    payload = JSON.parse(event.body);
  } catch (e) {
    console.log(`[ERROR] requestId=${requestId} source=${sourceService} msg=Invalid JSON payload from user-agent: ${userAgent}`);
    return { statusCode: 400, body: JSON.stringify({ error: 'Invalid JSON' }) };
  }

  const action = payload.action || 'unknown';
  const userId = payload.user_id || 'anonymous';
  const metadata = payload.metadata || {};

  // Structured logging for CloudWatch - includes user-controlled data
  console.log(`[INFO] requestId=${requestId} action=${action} userId=${userId} source=${sourceService} timestamp=${new Date().toISOString()}`);

  // Process different webhook actions
  if (action === 'user.created') {
    const email = payload.email || 'none';
    console.log(`[AUDIT] requestId=${requestId} event=USER_CREATED email=${email} userId=${userId} metadata=${JSON.stringify(metadata)}`);
    await processUserCreation(userId, email, metadata);
  } else if (action === 'payment.completed') {
    const amount = payload.amount || 0;
    const currency = payload.currency || 'USD';
    console.log(`[AUDIT] requestId=${requestId} event=PAYMENT_COMPLETED userId=${userId} amount=${amount} currency=${currency}`);
    await processPayment(userId, amount, currency);
  } else if (action === 'order.shipped') {
    const orderId = payload.order_id || 'unknown';
    const trackingNumber = payload.tracking_number || 'none';
    // Log includes multiple user-controlled fields without sanitization
    console.log(`[AUDIT] requestId=${requestId} event=ORDER_SHIPPED userId=${userId} orderId=${orderId} tracking=${trackingNumber}`);
    await processShipment(userId, orderId, trackingNumber);
  } else {
    console.log(`[WARN] requestId=${requestId} event=UNKNOWN_ACTION action=${action} userId=${userId} rawBody=${event.body}`);
  }

  // Log completion with timing
  console.log(`[INFO] requestId=${requestId} status=completed action=${action} userId=${userId}`);

  return {
    statusCode: 200,
    body: JSON.stringify({ status: 'processed', requestId })
  };
};

async function processUserCreation(userId, email, metadata) {
  // Simulate DynamoDB write
  const dynamodb = new AWS.DynamoDB.DocumentClient();
  await dynamodb.put({
    TableName: process.env.USERS_TABLE || 'users',
    Item: { userId, email, metadata, createdAt: Date.now() }
  }).promise();
}

async function processPayment(userId, amount, currency) {
  const dynamodb = new AWS.DynamoDB.DocumentClient();
  await dynamodb.put({
    TableName: process.env.PAYMENTS_TABLE || 'payments',
    Item: { userId, amount, currency, processedAt: Date.now() }
  }).promise();
}

async function processShipment(userId, orderId, trackingNumber) {
  const dynamodb = new AWS.DynamoDB.DocumentClient();
  await dynamodb.update({
    TableName: process.env.ORDERS_TABLE || 'orders',
    Key: { orderId },
    UpdateExpression: 'SET #s = :status, #t = :tracking',
    ExpressionAttributeNames: { '#s': 'status', '#t': 'trackingNumber' },
    ExpressionAttributeValues: { ':status': 'shipped', ':tracking': trackingNumber }
  }).promise();
}
